"""Self-test: verify that the numbers this project publishes are sound.

Three things are checked, and all three exist to protect a single promise:
*every number in the README can be regenerated by a script in this repo.*

1. **The cross-track error definition is the right one.** Measuring
   "distance to the nearest waypoint" is not cross-track error -- waypoints
   sit 1 m apart, so a robot exactly on the path is 0.5 m from the nearest
   waypoint half the time. The wrong metric returns a near-constant number
   that looks like half a grid cell and hides the effect of every parameter.
   This test pins the correct behaviour and documents the contrast.

2. **The vectorised metric equals the per-point loop.** ``src/metrics.py``
   computes cross-track error with numpy for speed; the reference loop in
   ``tools/benchmark_ref.py`` computes it the obvious way. They must agree
   exactly, or the tables mean different things.

3. **Runs are deterministic.** The same inputs must give the same metrics,
   or a "measured" number is just noise.

Run:

    python tools/selftest.py
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import numpy as np                                                    # noqa: E402

from src.metrics import crosstrack_error, measure, dist_point_to_segment  # noqa: E402
from src.simulation import build_world                                 # noqa: E402

from benchmark_ref import evaluate as ref_evaluate                    # noqa: E402
from benchmark_ref import make_map as ref_make_map                    # noqa: E402

TOL = 1e-9
ROUNDED_TOL = 1e-4          # src/metrics.py rounds to the README's precision
failures = []


def check(name, a, b, tol=TOL):
    ok = abs(a - b) <= tol
    print(f"  {'PASS' if ok else 'FAIL'}  {name}: {a} vs {b}")
    if not ok:
        failures.append(name.strip())


print("1. src/metrics.py vs the independent reference implementation\n")

_, ref_path, ref_waypoints = ref_make_map()

for params in (
    {"tol": 0.05, "speed": 0.5, "Kp": 5.0},
    {"tol": 0.02, "speed": 0.5, "Kp": 5.0},
    {"tol": 0.30, "speed": 0.5, "Kp": 5.0},
    {"tol": 0.05, "speed": 1.5, "Kp": 5.0},
    {"tol": 0.05, "speed": 0.3, "Kp": 5.0},
    {"tol": 0.05, "speed": 0.5, "Kp": 12.0},
    {"tol": 0.05, "speed": 0.5, "Kp": 2.0},
):
    label = f"tol={params['tol']} speed={params['speed']} Kp={params['Kp']}"
    ref = ref_evaluate(ref_waypoints, **params)
    mine = measure(build_world(size=10, start=(1, 1), goal=(8, 8), **params))

    print(f" {label}")
    check("  time", mine["time_s"], ref["time"], tol=1e-6)
    check("  distance", mine["distance_m"], ref["dist"], tol=1e-6)
    check("  end-point error", mine["end_point_error_m"], ref["end_err"], tol=ROUNDED_TOL)
    check("  max cross-track", mine["max_cross_track_m"], ref["max_ct"], tol=ROUNDED_TOL)
    check("  mean cross-track", mine["mean_cross_track_m"], ref["mean_ct"], tol=ROUNDED_TOL)
    print()

print("2. The cross-track definition itself\n")

# A trajectory lying exactly on the planned polyline must have zero error.
ct = crosstrack_error(ref_waypoints, ref_waypoints)
print(f"  {'PASS' if ct.max() < 1e-9 else 'FAIL'}  "
      f"trajectory exactly on the polyline -> max cross-track {ct.max():.2e} m")
if ct.max() >= 1e-9:
    failures.append("on-polyline cross-track")

# Vectorised vs per-point loop, on a real trajectory.
real_traj = build_world(size=10, start=(1, 1), goal=(8, 8))["traj"]
W = np.array(ref_waypoints)
A, B = W[:-1], W[1:]
loopy = np.array([min(dist_point_to_segment(np.array(p, dtype=float), A[i], B[i])
                       for i in range(len(A)))
                  for p in real_traj])
vectorised = crosstrack_error(real_traj, ref_waypoints)
same = np.allclose(loopy, vectorised, rtol=0, atol=1e-12)
print(f"  {'PASS' if same else 'FAIL'}  vectorised == per-point loop "
      f"(max abs diff {np.max(np.abs(loopy - vectorised)):.2e})")
if not same:
    failures.append("vectorised equivalence")

# The wrong metric, for contrast -- this is the trap the README warns about.
d_nearest_wp = np.array([np.min(np.hypot(p[0] - W[:, 0], p[1] - W[:, 1])) for p in real_traj])
print(f"  (the wrong metric 'distance to nearest waypoint' on the same trajectory: "
      f"{d_nearest_wp.mean():.3f} m mean, {d_nearest_wp.max():.3f} m max -- "
      f"not zero, so it does not measure error)")
print(f"   (the correct metric on that trajectory: {vectorised.mean():.4f} m mean, "
      f"{vectorised.max():.4f} m max)")
print()

print("3. Determinism\n")
w1 = measure(build_world(size=10, start=(1, 1), goal=(8, 8)))
w2 = measure(build_world(size=10, start=(1, 1), goal=(8, 8)))
same = all(abs(w1[k] - w2[k]) < TOL for k in w1)
print(f"  {'PASS' if same else 'FAIL'}  two identical runs agree")
if not same:
    failures.append("determinism")
print()

print("4. The agent loop is wired correctly (mock mode, no API calls)\n")
from src.agent import NavAgent                                        # noqa: E402
from src.nebius_client import TokenFactory                            # noqa: E402

client = TokenFactory(mock=True)
agent = NavAgent(client)
out = agent.autotune(instruction="Go from (1,1) to (8,8) around the wall.",
                      task={"start": [1, 1], "goal": [8, 8]},
                      rounds=2, verbose=False)
has_metrics = bool(out["best_metrics"]) and out["best_metrics"]["max_cross_track_m"] > 0
print(f"  {'PASS' if has_metrics else 'FAIL'}  the loop produced measured metrics "
      f"({out['rounds']} round(s), best max_ct="
      f"{out['best_metrics'].get('max_cross_track_m', float('nan')):.4f} m)")
if not has_metrics:
    failures.append("agent loop")

# And the map suite must be solvable -- otherwise the generalisation table
# would be measuring nothing.
from src.benchmark import build_suite, is_connected                  # noqa: E402

suite = build_suite(n_random=4)
all_connected = all(is_connected(g, (1, 1), (8, 8)) for _, g in suite)
print(f"  {'PASS' if all_connected else 'FAIL'}  all {len(suite)} suite maps are solvable")
if not all_connected:
    failures.append("suite connectivity")
print()

if failures:
    print(f"SELFTEST FAILED - {len(failures)} check(s): {failures}")
    sys.exit(1)
print("SELFTEST PASSED - all checks green.")
